package com.bank.oom;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Simulates the classic "Java heap space" OOM: an unbounded cache of transactions.
class HeapExhaustionDemo {
    private static final Logger log = Logger.getLogger(HeapExhaustionDemo.class.getName());
    // A static list that is NEVER cleared → every object is retained forever (leak).
    private static final List<BigDecimal[]> LEAK = new ArrayList<>();

    static void run() {
        log.info("Simulating 'Java heap space' with an unbounded transaction cache");
        try {
            while (true) {
                // each entry holds a chunk of memory representing cached statement rows
                LEAK.add(new BigDecimal[100_000]);
            }
        } catch (OutOfMemoryError e) {
            log.severe("CAUGHT: java.lang.OutOfMemoryError: " + e.getMessage()
                + " → heap full; take a heap dump, inspect the LEAK list retention");
            LEAK.clear();     // release so the JVM survives the demo
        }
    }
}
