package com.bank.oom;

import java.nio.ByteBuffer;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Simulates "Direct buffer memory": off-heap NIO buffers past -XX:MaxDirectMemorySize.
class DirectBufferDemo {
    private static final Logger log = Logger.getLogger(DirectBufferDemo.class.getName());

    static void run() {
        log.info("Simulating 'Direct buffer memory' with un-freed direct ByteBuffers");
        List<ByteBuffer> buffers = new ArrayList<>();   // holds references → never cleaned
        try {
            while (true) {
                buffers.add(ByteBuffer.allocateDirect(16 * 1024 * 1024));   // 16MB off-heap
            }
        } catch (OutOfMemoryError e) {
            log.severe("CAUGHT: java.lang.OutOfMemoryError: " + e.getMessage()
                + " → off-heap, NOT on the Java heap; raise -XX:MaxDirectMemorySize or"
                + " release buffers; a heap dump will NOT show this");
            buffers.clear();
        }
    }
}
