package com.bank.oom;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.logging.Logger;

// Simulates "unable to create native thread": OS refuses more threads.
class NativeThreadDemo {
    private static final Logger log = Logger.getLogger(NativeThreadDemo.class.getName());

    static void run() {
        log.info("Simulating 'unable to create native thread' (thread-per-request design)");
        List<Thread> threads = new ArrayList<>();
        CountDownLatch hold = new CountDownLatch(1);
        try {
            while (true) {
                Thread t = new Thread(() -> {
                    try { hold.await(); } catch (InterruptedException ignored) { }
                });
                t.start();
                threads.add(t);
            }
        } catch (OutOfMemoryError e) {
            log.severe("CAUGHT: java.lang.OutOfMemoryError: " + e.getMessage()
                + " → OS limit, not heap; pool threads, lower -Xss, raise ulimit,"
                + " or use virtual threads");
        } finally {
            hold.countDown();   // release threads so the JVM survives
        }
    }
}
