package com.bank.oom;

import java.util.logging.Logger;

public class OomTypesDemo {
    private static final Logger log = Logger.getLogger(OomTypesDemo.class.getName());

    public static void main(String[] args) {
        // Metaspace + Compressed class space are explained (not triggered) to stay safe;
        // they come from loading too many classes (classloader leaks, dynamic proxies).
        log.info("Metaspace OOM → native class-metadata region full (classloader leak);"
            + " cap with -XX:MaxMetaspaceSize, watch loaded-class count");
        log.info("Compressed class space OOM → capped class-pointer region full;"
            + " raise -XX:CompressedClassSpaceSize or load fewer classes");
        log.info("GC overhead limit exceeded → >98% time in GC, <2% reclaimed;"
            + " same root cause as heap space (near-full thrashing heap)");

        HeapExhaustionDemo.run();
        DirectBufferDemo.run();
        NativeThreadDemo.run();
    }
}
